import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './kbd.module.css'

export interface KbdProps extends HTMLAttributes<HTMLElement> {
  size?: 'sm' | 'md'
}

export function Kbd({ size = 'md', className, children, ...props }: KbdProps) {
  return (
    <kbd data-size={size} className={cn(styles['kbd'], className)} {...props}>
      {children}
    </kbd>
  )
}

@layer cascivo.component {
  .kbd {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-family: var(--cascivo-font-mono);
    font-weight: var(--cascivo-font-medium);
    line-height: 1;
    color: var(--cascivo-color-text-subtle);
    background-color: var(--cascivo-color-surface-raised);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-indicator);
    box-shadow: inset 0 -1px 0 var(--cascivo-color-border-strong);
    white-space: nowrap;

    &[data-size='sm'] {
      min-inline-size: 1.25rem;
      padding-block: var(--cascivo-space-0);
      padding-inline: var(--cascivo-space-1);
      font-size: var(--cascivo-text-xs);
      block-size: 1.25rem;
    }

    &[data-size='md'] {
      min-inline-size: 1.5rem;
      padding-block: var(--cascivo-space-1);
      padding-inline: var(--cascivo-space-2);
      font-size: var(--cascivo-text-sm);
      block-size: 1.5rem;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Kbd',
  description: 'Displays a keyboard key or shortcut',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: ['sm', 'md'],
  props: [
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md'",
      required: false,
      default: 'md',
    },
  ],
  tokens: [
    '--cascivo-color-text-subtle',
    '--cascivo-color-surface-raised',
    '--cascivo-color-border',
    '--cascivo-color-border-strong',
    '--cascivo-radius-sm',
  ],
  accessibility: {
    role: 'kbd',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Single key', code: '<Kbd>⌘</Kbd>' },
    {
      title: 'Shortcut',
      code: '<span><Kbd>⌘</Kbd> + <Kbd>K</Kbd></span>',
      description: 'Compose multiple keys to show a shortcut',
    },
    { title: 'Small', code: '<Kbd size="sm">Esc</Kbd>' },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['keyboard', 'shortcut', 'hotkey'],
  intent: {
    whenToUse: [
      'Showing a keyboard key or shortcut the user should press',
      'Documenting hotkeys in menus, tooltips, or help text',
    ],
    whenNotToUse: [
      'Inline code, commands, or identifiers — use Code',
      'A short label that is not a key press — use Badge or Text',
    ],
    antiPatterns: [
      {
        bad: '<Kbd>npm install</Kbd>',
        good: '<Code>npm install</Code>',
        why: 'Kbd is for keys to press, not shell commands or code',
      },
    ],
    related: [
      {
        name: 'Code',
        relationship: 'alternative',
        reason: 'Code marks literal code; Kbd marks keys to press',
      },
    ],
    a11yRationale:
      'Renders a native <kbd> element so assistive tech identifies the content as keyboard input; compose multiple <kbd> for a chord rather than encoding the combination in one string',
    flexibility: [
      {
        area: 'size',
        level: 'flexible',
        note: 'sm fits inline help; md matches body text',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Surface and border must resolve to --cascivo-* tokens',
      },
    ],
  },
}
